- How would you modify to support deletion safely?
- How does memory scale with the corpus size, and alternatives like compressed tries?

## Why This Is Asked

This question tests your understanding of counting DP, covering both memoization (top-down) and tabulation (bottom-up) approaches, along with space optimization and edge-case handling.

## Key Concepts

- Subset sum counting with each element used at most once
- Memoization (top-down) with recursive DFS and memo table
- Tabulation (bottom-up) with 1D space optimization to O(S)
- Modulo arithmetic to prevent integer overflow

## Edge Cases

- **Empty subset (N=0)**: If N=0 and S=0, return 1 (one valid subset - empty set). If S>0, return 0.
- **Target S=0**: Always return 1 (the empty subset counts as one valid subset).
- **All elements greater than S**: No valid subsets exist, return 0.

## Code Example

```javascript
function countSubsets(nums, target) {
  const mod = 1_000_000_007;
  const n = nums.length;

  // Top-down with memoization
  const memo = Array.from({ length: n + 1 }, () => Array(target + 1).fill(-1));
  function dfs(i, s) {
    if (s === 0) return 1;
    if (i === 0) return 0;
    if (memo[i][s] !== -1) return memo[i][s];
    memo[i][s] = dfs(i - 1, s) % mod;
    if (s >= nums[i - 1]) {
      memo[i][s] = (memo[i][s] + dfs(i - 1, s - nums[i - 1])) % mod;
    }
    return memo[i][s];
  }
  return dfs(n, target);
}

// Bottom-up with space optimization
function countSubsetsBU(nums, target) {
  const mod = 1_000_000_007;
  const dp = Array(target + 1).fill(0);
  dp[0] = 1;

  for (const num of nums) {
    for (let s = target; s >= num; s--) {
      dp[s] = (dp[s] + dp[s - num]) % mod;
    }
  }
  return dp[target];
}
```

Both solutions run in O(N×S) time with the bottom-up approach using O(S) space.

## Why This Is Asked
This question tests mastery of three key concepts: Trie mutations (insert/delete), weighted dynamic programming for word break problems, and the ability to implement both iterative and recursive approaches. It also evaluates understanding of handling dynamic dictionary updates and edge cases such as when no valid decomposition exists.

## Key Concepts
- Trie with terminal weights for efficient prefix matching
- Dynamic insert/delete operations on Trie structure
- Weighted word-break DP with O(n × L) complexity where L = maxWordLen
- Both iterative bottom-up DP and memoized top-down DFS variants

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.endWeight = 0;
    this.isEnd = false;
  }
}

class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
    this.maxWordLen = 0;
  }

  insert(word, weight) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
    }
    node.isEnd = true;
    node.endWeight = weight;
    this.maxWordLen = Math.max(this.maxWordLen, word.length);
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) return;
      node = node.children.get(char);
    }
    node.isEnd = false;
    node.endWeight = 0;
  }

  maxPartition(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(-1);
    dp[n] = 0;

    for (let i = n - 1; i >= 0; i--) {
      let node = this.root;
      for (let j = i; j < Math.min(n, i + this.maxWordLen); j++) {
        const char = s[j];
        if (!node.children.has(char)) break;
        node = node.children.get(char);
        if (node.isEnd && dp[j + 1] !== -1) {
          dp[i] = Math.max(dp[i], node.endWeight + dp[j + 1]);
        }
      }
    }
    return dp[0];
  }

  maxPartitionDFS(s, memo = {}) {
    if (s.length === 0) return 0;
    if (s in memo) return memo[s];

    let maxWeight = -1;
    let node = this.root;

    for (let i = 0; i < Math.min(s.length, this.maxWordLen); i++) {
      const char = s[i];
      if (!node.children.has(char)) break;
      node = node.children.get(char);

      if (node.isEnd) {
        const remaining = this.maxPartitionDFS(s.slice(i + 1), memo);
        if (remaining !== -1) {
          maxWeight = Math.max(maxWeight, node.endWeight + remaining);
        }
      }
    }
    memo[s] = maxWeight;
    return maxWeight;
  }
}
```

